import { useState } from "react";
import { useNavigate } from "react-router-dom";
import { Card, CardContent, Typography, Grid, Avatar, Button } from '@mui/material';
import axios from 'axios';


const Login = () => {
    const navigate = useNavigate();
    const [formData, setFormData] = useState({ numElecteur: "", numCNI: "" });
    const [errorMessage, setErrorMessage] = useState("");

    const handleChange = (e) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setErrorMessage(""); // Réinitialiser le message d'erreur

        try {
            const res = await axios.post("http://localhost:5000/api/login-elector", formData);  // 🔹 Correction URL
            if (res.data.success) {
                console.log("Données envoyées à VerifyOTP:", res.data.elector);
                navigate("/verify-otp", { state: { ...res.data.elector, numElecteur: formData.numElecteur } });
            } else {
                setErrorMessage("Numéro d’électeur ou CNI incorrect.");
            }
        } catch (error) {
            console.error("Erreur:", error);
            setErrorMessage("Erreur de connexion au serveur.");
        }
    };

    return (
        <div className="login-container">
            <h2>Connexion</h2>
            {errorMessage && <p className="error-message">{errorMessage}</p>}
            <form onSubmit={handleSubmit}>
                <input type="text" name="numElecteur" placeholder="Numéro d’électeur" onChange={handleChange} required />
                <input type="text" name="numCNI" placeholder="Numéro CNI" onChange={handleChange} required />
                <button type="submit">Se connecter</button>
            </form>
        </div>
    );
};

export default Login;
